import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DevFix","text":"Autonomous Environment Recovery","tagline":"Top 1% Hackathon Agent. Automatically detects, diagnoses, and fixes broken local development environments.","actions":[{"theme":"brand","text":"Get Started","link":"/changelog"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/ghulam-mustafa/devfix"}]},"features":[{"title":"80% Success Rate","details":"Achieves top-tier performance on the rigorous 10-case DevFix benchmark."},{"title":"Secure & Sandboxed","details":"Runs completely inside isolated Docker containers with restricted network access."},{"title":"Language Agnostic","details":"Automatically detects and supports Node.js, TypeScript, and Python out of the box."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function s(r,e,c,l,d,m){return a(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="what-is-devfix" tabindex="-1">What is DevFix? <a class="header-anchor" href="#what-is-devfix" aria-label="Permalink to &quot;What is DevFix?&quot;">​</a></h2><p>DevFix is an AI-powered CLI agent designed to solve the &quot;it works on my machine&quot; problem. When a local project refuses to build or start, you simply run <code>devfix inspect .</code>, and the agent will:</p><ol><li><strong>Observe:</strong> Inspect configurations, package managers, and runtimes using static analysis.</li><li><strong>Execute:</strong> Spin up a secure Docker sandbox and attempt to run the project.</li><li><strong>Diagnose:</strong> Analyze stack traces, missing dependencies, and build failures.</li><li><strong>Fix:</strong> Interactively patch code, install packages, and re-run until the environment is healthy.</li></ol><h2 id="the-benchmark" tabindex="-1">The Benchmark <a class="header-anchor" href="#the-benchmark" aria-label="Permalink to &quot;The Benchmark&quot;">​</a></h2><p>DevFix was aggressively optimized against a custom deterministic benchmark of common local failures (e.g. missing <code>node_modules</code>, broken <code>package.json</code>, malformed <code>tsconfig.json</code>, syntax errors, and missing system binaries).</p><p>Through careful prompt engineering, robust tool design, and context management, the <code>deepseek-chat</code> powered agent recovers 8/10 severely broken environments completely autonomously.</p>',6)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
